def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bars = []
    for r, row in enumerate(grid):
        cells = [c for c, v in enumerate(row) if v]
        if len(cells) >= 4:
            bars.append((r, min(cells), max(cells), cells))
    # Vertical guides are identified by multiple cells in the same column.
    guide_cols = [c for c in range(w) if sum(grid[r][c] != 0 for r in range(h)) >= 2]
    # Draw from each bar gap along its column, using the color on the side that
    # reaches the guide; neighboring bars set where that colored segment ends.
    for c in guide_cols:
        crossings = []
        for r, lo, hi, cells in bars:
            if lo <= c <= hi:
                col = grid[r][c]
                if col == 0:
                    col = next((grid[r][x] for x in range(c + 1, hi + 1) if grid[r][x]),
                               next((grid[r][x] for x in range(c - 1, lo - 1, -1) if grid[r][x]), 0))
                if col:
                    crossings.append((r, col))
        for i, (r, col) in enumerate(crossings):
            start = 0 if i == 0 else crossings[i - 1][0] + 1
            for rr in range(start, r + 1):
                out[rr][c] = col
    # Complete horizontal bars without overwriting vertical lines.
    for r, lo, hi, cells in bars:
        colors = [grid[r][c] for c in cells]
        for c in range(lo, hi + 1):
            if out[r][c] == 0:
                out[r][c] = grid[r][cells[0]]
    return out
